1	// 运行在页面 MAIN world：hook window.fetch 与 XMLHttpRequest，
2	// 截获 Temu 后台商品接口的响应 JSON，通过 postMessage 传给 content.js（隔离世界）。
3	// 只读、不改请求；请求本身仍由页面自己发出（自带 cookie + anti-content 签名），故不触发风控。
4	(function () {
5	  if (window.__temuMonHooked) return;
6	  window.__temuMonHooked = true;
7	
8	  // 关注接口：countStatus（各状态计数）、pageQuery（商品列表）、skuSpecList（SKU 规格列表）、skuPriceQuery（SKU 建议价）
9	  const MATCH = /(visage-agent-seller\/product\/skc\/(countStatus|pageQuery)|anniston-agent-seller\/sku\/spec\/parent\/list|visage-agent-seller\/product\/sku\/site\/suggestedPrice\/gray\/query)\b/;
10	  function kindOf(url) {
11	    if (/countStatus/.test(url)) return 'countStatus';
12	    if (/skc\/pageQuery/.test(url)) return 'pageQuery';
13	    if (/sku\/spec\/parent\/list/.test(url)) return 'skuSpecList';
14	    if (/suggestedPrice\/gray\/query/.test(url)) return 'skuPriceQuery';
15	    return null;
16	  }
17	
18	  // 从请求头 / cookie 里找出当前店铺 id（多店铺时用来区分是哪个店）
19	  function findMallInHeaders(hdrs) {
20	    if (!hdrs) return null;
21	    for (const k of Object.keys(hdrs)) {
22	      if (/mall.?id/i.test(k) && /^\d{6,}$/.test(String(hdrs[k]).trim())) return String(hdrs[k]).trim();
23	    }
24	    return null;
25	  }
26	  function findMallInCookie() {
27	    try {
28	      const m = document.cookie.match(/(?:^|;\s*)[^=]*mall[^=]*id[^=]*=(\d{6,})/i);
29	      if (m) return m[1];
30	    } catch (e) { /* ignore */ }
31	    return null;
32	  }
33	  function headersToObj(h) {
34	    const o = {};
35	    try {
36	      if (!h) return o;
37	      if (typeof Headers !== 'undefined' && h instanceof Headers) h.forEach((v, k) => (o[String(k).toLowerCase()] = v));
38	      else if (Array.isArray(h)) for (const pair of h) o[String(pair[0]).toLowerCase()] = pair[1];
39	      else for (const k of Object.keys(h)) o[String(k).toLowerCase()] = h[k];
40	    } catch (e) { /* ignore */ }
41	    return o;
42	  }
43	
44	  function post(url, body, mallId) {
45	    const kind = kindOf(url);
46	    if (!kind || !body) return;
47	    try {
48	      window.postMessage({ __temuMon: true, kind, url: String(url), body: String(body), mallId: mallId || findMallInCookie() || null }, '*');
49	    } catch (e) { /* ignore */ }
50	  }
51	
52	  // ---- fetch ----
53	  const origFetch = window.fetch;
54	  window.fetch = function (...args) {
55	    return origFetch.apply(this, args).then((resp) => {
56	      try {
57	        let url = (resp && resp.url) || '';
58	        if (!url) url = typeof args[0] === 'string' ? args[0] : (args[0] && args[0].url) || '';
59	        if (MATCH.test(url)) {
60	          const hdrs = headersToObj(args[1] && args[1].headers);
61	          const mallId = findMallInHeaders(hdrs);
62	          resp.clone().text().then((t) => post(url, t, mallId)).catch(() => {});
63	        }
64	      } catch (e) { /* ignore */ }
65	      return resp;
66	    });
67	  };
68	
69	  // ---- XMLHttpRequest ----
70	  const origOpen = XMLHttpRequest.prototype.open;
71	  const origSend = XMLHttpRequest.prototype.send;
72	  const origSetHeader = XMLHttpRequest.prototype.setRequestHeader;
73	  XMLHttpRequest.prototype.open = function (method, url, ...rest) {
74	    this.__temuUrl = url;
75	    return origOpen.call(this, method, url, ...rest);
76	  };
77	  XMLHttpRequest.prototype.setRequestHeader = function (name, value) {
78	    try { (this.__temuHdrs = this.__temuHdrs || {})[String(name).toLowerCase()] = value; } catch (e) { /* ignore */ }
79	    return origSetHeader.apply(this, arguments);
80	  };
81	  XMLHttpRequest.prototype.send = function (...a) {
82	    this.addEventListener('load', () => {
83	      try {
