213	// 所有 stores 的读-改-写必须走 withStores，否则并发会互相覆盖 snapshot
214	//（典型：chipStats 的 updateStoreLatest 盖掉 _diffAndAlert 刚写入的 alertedTrafficIds
215	//  → 切店后再扫同一批限流商品被当成「新出现」重复飞书）。
216	let storesChain = Promise.resolve();
217	function withStores(fn) {
218	  const run = storesChain.then(() => fn());
219	  // 成功/失败都继续队列，避免一条 rejection 卡死后续写入
220	  storesChain = run.then(() => {}, () => {});
221	  return run;
222	}
223	async function getStores() {
224	  const { stores } = await chrome.storage.local.get('stores');
225	  return stores || {};
226	}
227	async function saveStores(stores) {
228	  await chrome.storage.local.set({ stores });
229	}
230	// 更新某店的最新读数（串行）
231	async function updateStoreLatest(name, patch) {
232	  return withStores(async () => {
233	    const stores = await getStores();
234	    const s = stores[name] || { latest: {}, snapshot: {} };
235	    s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
236	    stores[name] = s;
237	    await saveStores(stores);
238	    return s;
239	  });
240	}
241	// 合并 patch 到 snapshot（串行），供 mustRemind / sku diff 等使用
242	async function updateStoreSnapshot(name, snapPatch) {
243	  return withStores(async () => {
244	    const stores = await getStores();
245	    const s = stores[name] || { latest: {}, snapshot: {} };
246	    s.snapshot = Object.assign({}, s.snapshot || {}, snapPatch);
247	    stores[name] = s;
248	    await saveStores(stores);
249	    return s;
250	  });
251	}
252	// alerted map 是否已有有效基线（空 {} 不算——否则首次空池 seed 后，明细一出现会全量误报）
253	function alertedMapSize(map) {
254	  return map && typeof map === 'object' ? Object.keys(map).length : 0;
255	}
256	function hasTrafficBaseline(snap) {
257	  if (!snap || typeof snap !== 'object') return false;
258	  // v18：仅 trafficBaselineAt 但 alerted 为空 → 不可信（可能是半截写入），不算 ready
259	  const n = alertedMapSize(snap.alertedTrafficIds)
260	    + alertedMapSize(snap.alertedWatchIds)
261	    + alertedMapSize(snap.alertedDeclineIds);
262	  if (n > 0) return true;
263	  return false;
264	}
265	// 全账号级别的 productId 冷却（不按店）。切店/snapshot 丢失时仍能挡住同一 SPU 重复推。
266	async function getGlobalAlerted() {
267	  const { trafficAlertedGlobal } = await chrome.storage.local.get('trafficAlertedGlobal');
268	  return trafficAlertedGlobal || {};
269	}
