function parseHHMM(s) {
  const m = String(s || '').trim().match(/^(\d{1,2})[:.：](\d{2})$/);
  if (!m) return null;
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) return null;
  return { h, min, label: String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0') };
}
