      );
      if (!Object.keys(prevMap).length) {
        lines.push('_本时点建立限流基准 ' + pool.length + ' 条，不报差异_');
      } else if (!storeDiff) {
        lines.push('_限流无变化_');
      } else {
        if (added.length) {
          lines.push('新增限流 **' + added.length + '**：');
          lines.push(...itemLines(added, added.length));
