    // from/to 用「本轮结束后的确认基准」表达，避免和 pending 混淆
    const fromN = prevIds.length;
    // to 先按公式，最终与 nextOnSaleMap 对齐（下面构建后回填）
    let toN = fromN - delisted.length + listed.length;
