    if (!skipUpdate && delisted.length) {
      events.push({
        type: 'delist',
        severity: 'alert',
        items: delisted.map((id) => ({
          skcId: id,
          parentId: (allMap[id] || prevMap[id])?.parentId || '',
          name: (allMap[id] || prevMap[id])?.name || '',
