 */
async function diffOnSaleCount(name, onSaleCount) {
  if (!ONSALE_MONITOR_IN_PLUGIN || !ONSALE_QTY_ALERT) return null;
  if (typeof onSaleCount !== 'number' || onSaleCount < 0 || !Number.isFinite(onSaleCount)) return null;

  const cfg = await getConfig();
  if (!cfg.enabled) return null;
  const now = Date.now();

  const decision = await withStores(async () => {
    const stores = await getStores();
    const s = stores[name] || { latest: {}, snapshot: {} };
    const snap = s.snapshot || {};
    const prev = typeof snap.onSaleCount === 'number' ? snap.onSaleCount : null;
    // 写最新数量进 snapshot（与 latest 对齐）
    const newSnap = Object.assign({}, snap, { onSaleCount: onSaleCount, onSaleCountTs: now });
    s.snapshot = newSnap;
    stores[name] = s;
    await saveStores(stores);

    if (prev == null) {
      log.info('OnSale count baseline: store=' + name + ' count=' + onSaleCount);
      return { first: true, from: null, to: onSaleCount, dropped: 0, rose: 0, shouldScan: false };
    }
    if (prev === onSaleCount) {
      return { first: false, from: prev, to: onSaleCount, dropped: 0, rose: 0, shouldScan: false };
