// 解析店铺名：优先页面读到的真店名；拒绝颜色/规格假名；读不到才回退
async function resolveStore(msgStore) {
  if (msgStore && String(msgStore).trim()) {
    const n = String(msgStore).trim();
    if (!isFakeStoreName(n)) return n;
    log.warn('Rejected fake store name: ' + n);
