  // 回退：仅当 storage 里只有 1 个真店时用它；否则用配置名；再否则 null（调用方跳过写入）
  const stores = await getStores();
  const known = Object.keys(stores).filter((n) => n && !isFakeStoreName(n));
  if (known.length === 1) return known[0];
